INSERT INTO `banners` VALUES (1,'DINH DƯỠNG THÚ CƯNG 2026','Thực Đơn Vàng Cho Chó Mèo','TIẾT KIỆM TỚI 25%','Thức ăn hạt, pate mọng nước & bánh thưởng chính hãng bảo vệ hệ tiêu hóa','Mua ngay','https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=1000','#0284C7',1,'active','2026-10-11 15:48:23'),(3,'SIÊU SALE 10.10','Tuần Lễ Pate & Thức Ăn Ướt','MUA 2 TẶNG 1','Whiskas, Me-O, Kit Cat nhập khẩu thơm ngon ngậy vị','Xem ưu đãi','https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=1000','#D97706',3,'active','2026-10-11 16:54:35'),(4,'CHĂM SÓC DA LÔNG','Bí Quyết Sở Hữu Bộ Lông Mượt','GIẢM 20% DẦU CÁ','Dầu cá hồi Na Uy nguyên chất chống rụng lông hiệu quả','Khám phá','https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=1000','#7C3AED',4,'active','2026-10-11 16:54:35'),(5,'CÁT HỮU CƠ 2026','Cát Đậu Nành Tofu Xả Bồn Cầu','ĐỒNG GIÁ 99K','Không bụi 99%, an toàn hô hấp cho mèo con và sen','Mua ngay','https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=1000','#059669',5,'active','2026-10-11 16:54:35'),(6,'BÁNH THƯỞNG GIÁ TỐT','Ciao Churu Bánh Thưởng Mèo Số 1','GIẢM TỚI 25%','Sốt kem bổ sung collagen và tinh chất trà xanh khử mùi','Săn deal','https://images.unsplash.com/photo-1541599540903-216a46ca1dc0?w=1000','#E11D48',6,'active','2026-10-11 16:54:35'),(7,'DÒNG CAO CẤP GRAIN-FREE','Orijen & Acana Thuần Khiết Đạm','TIẾT KIỆM 100K','Không ngũ cốc độn, chuẩn sinh học tự nhiên cho chó mèo','Trải nghiệm','https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=1000','#2563EB',7,'active','2026-10-11 16:54:35'),(8,'GIAO HÀNG HỎA TỐC','PetCare Express Giao 2 Giờ','FREESHIP TỪ 300K','Nhận hàng tận cửa, túi zip đóng gói chống ẩm cao cấp','Đặt ngay','https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=1000','#0284C7',8,'active','2026-10-11 16:54:35'),(9,'NHA KHOA THÚ CƯNG','Pedigree DentaStix Giảm Cao Răng','GIẢM 15% MỌI CỠ','Thiết kế rãnh chữ X làm sạch sâu mảng bám răng cún','Xem ngay','https://images.unsplash.com/photo-1535294435445-d7249524ef2e?w=1000','#F59E0B',9,'active','2026-10-11 16:54:35'),(10,'SỨC KHỎE TOÀN DIỆN','Gel Dinh Dưỡng Nourse 21','MUA 1 TẶNG SNACK','Bổ sung 18 acid amin thiết yếu cho thú cưng ốm dậy','Mua ngay','https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=1000','#10B981',10,'active','2026-10-11 16:54:35'),(11,'THÀNH VIÊN PETCARE VIP','Tích Điểm PetXu Đổi Quà Khủng','HOÀN TIỀN 5%','Nâng hạng Bạc, Vàng, Kim Cương nhận quà sinh nhật','Đăng ký','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=1000','#8B5CF6',11,'active','2026-10-11 16:54:35'),(12,'GIẢI PHÁP TIÊU LÔNG','Gel Tiêu Lông GimCat Đức','GIẢM NGAY 30K','Bảo vệ đường ruột, không còn ho nôn khan khó chịu','Xem chi tiết','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=1000','#EC4899',12,'active','2026-10-11 16:54:35'),(13,'VỆ SINH MÙA MƯA','Sữa Tắm Thảo Mộc Forcans Hàn Quốc','GIẢM 18%','Ngừa nấm ngứa da lông và lưu hương phấn dịu nhẹ 5 ngày','Khám phá','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=1000','#06B6D4',13,'active','2026-10-11 16:54:35'),(14,'ĐẶC TRỊ VE RẬN','Frontline & NexGard Chính Hãng','BẢO VỆ 30 NGÀY','Diệt sạch 100% bọ chét ve rận chỉ sau 24h an toàn','Mua thuốc','https://images.unsplash.com/photo-1535294435445-d7249524ef2e?w=1000','#3B82F6',14,'active','2026-10-11 16:54:35'),(15,'PHỤ KIỆN DU LỊCH','Balo Phi Hành Gia Trong Suốt','GIẢM 50K','Chống sốc thông thoáng chuẩn hàng không vi vu cùng sen','Xem mẫu','https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=1000','#F97316',15,'active','2026-10-11 16:54:35'),(16,'THỨC ĂN HẠT MỀM','Zenith Nhập Khẩu Hàn Quốc','HẠT MỀM DỄ NHAI','Dành riêng cho cún kén ăn và thú cưng răng yếu','Dùng thử','https://images.unsplash.com/photo-1537151625747-768eb6cf92b2?w=1000','#6366F1',16,'active','2026-10-11 16:54:35'),(17,'BÁT ĂN CHỐNG GÙ','Bát Nghiêng 15 Độ Inox 304','ĐỒNG GIÁ 89K','Bảo vệ đốt sống cổ và chống mụn cằm vi khuẩn','Đặt mua','https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=1000','#14B8A6',17,'active','2026-10-11 16:54:35'),(18,'CỎ TƯƠI CHO MÈO','Cỏ Lúa Mạch Hữu Cơ Tươi Ngon','MUA 2 TẶNG 1','Bổ sung chất xơ tự nhiên hỗ trợ tiêu hóa êm dịu','Mua ngay','https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=1000','#22C55E',18,'active','2026-10-11 16:54:35'),(19,'SNACK SẤY THĂNG HOA','100% Ức Gà Freeze-Dried','GIẢM 20%','Giữ trọn 98% vi chất thịt tươi nguyên bản không độn bột','Thưởng thức','https://images.unsplash.com/photo-1541599540903-216a46ca1dc0?w=1000','#EAB308',19,'active','2026-10-11 16:54:35'),(20,'ĐỒ CHƠI GIẢM STRESS','Bóng Cao Su Tự Nhiên KONG USA','BẢO HÀNH CẮN VỠ','Chống cắn phá đồ đạc trong nhà khi chủ vắng mặt','Xem ngay','https://images.unsplash.com/photo-1535294435445-d7249524ef2e?w=1000','#A855F7',20,'active','2026-10-11 16:54:35'),(21,'LƯƠNG VỀ KHAO BOSS','Flash Sale Đồng Giá Từ 19K','CHỈ TRONG 3 NGÀY','Hàng nghìn lon pate và bánh thưởng ưu đãi cực sâu','Săn ngay','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=1000','#EF4444',21,'active','2026-10-11 16:54:35'),(22,'VOUCHER ĐỘC QUYỀN','Nhập PETCARE10 Giảm 10%','ÁP DỤNG TOÀN SÀN','Áp dụng cho mọi đơn hàng thức ăn phụ kiện','Lấy mã','https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=1000','#0284C7',22,'active','2026-10-11 16:54:35'),(23,'SỮA BỘT SƠ SINH','Sữa Dê Bột Kháng Thể PetLac','GIẢM 15%','Thay thế sữa mẹ hoàn hảo cho cún mèo sơ sinh mất mẹ','Xem sữa','https://images.unsplash.com/photo-1533738363-b7f9aef128ce?w=1000','#38BDF8',23,'active','2026-10-11 16:54:35'),(24,'MEN VI SINH SỐNG','Lợi Khuẩn Đường Ruột Cấp Tốc','CHỐNG TIÊU CHẢY','Cân bằng hệ vi sinh đường ruột khi đổi thức ăn mới','Tìm hiểu','https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=1000','#4ADE80',24,'active','2026-10-11 16:54:35'),(25,'TRIỆT SẢN AN TOÀN','Phẫu Thuật Nội Soi Không Đau','TẶNG VÒNG CHỐNG LIẾM','Đội ngũ bác sĩ thú y ngoại khoa 10 năm kinh nghiệm','Đặt lịch','https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=1000','#818CF8',25,'active','2026-10-11 16:54:35'),(26,'CHĂM SÓC RĂNG MIỆNG','Combo Xịt Thơm Miệng & Bàn Chải','GIẢM 25%','Sạch mảng bám vôi răng không lo hôi miệng khi gần sen','Mua combo','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=1000','#FB7185',26,'active','2026-10-11 16:54:35'),(27,'HỘ CHIẾU THÚ CƯNG','Khám Chứng Nhận Sức Khỏe Bay','CHUẨN QUỐC TẾ','Cấp sổ tiêm microchip vi vu cùng boss khắp thế giới','Tư vấn bay','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=1000','#34D399',27,'active','2026-10-11 16:54:35'),(28,'MÁY LỌC NƯỚC THÔNG MINH','Nước Tuần Hoàn Lọc Cảm Ứng','MÈO UỐNG NƯỚC NHIỀU HƠN','Ngăn ngừa sỏi thận bàng quang hiệu quả bất ngờ','Xem máy','https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=1000','#60A5FA',28,'active','2026-10-11 16:54:35'),(29,'ĐỆM LÔNG CỪU ẤM ÁP','Ổ Nằm Cao Cấp Chống Lạnh Khớp','GIẢM 30%','Mềm mại êm ái cho thú cưng giấc ngủ sâu trọn vẹn','Chọn size','https://images.unsplash.com/photo-1552053831-71594a27632d?w=1000','#F472B6',29,'active','2026-10-11 16:54:35'),(30,'CẨM NANG THÚ Y 2026','Tra Cứu Dinh Dưỡng Chuẩn AAFCO','HOÀN TOÀN MIỄN PHÍ','Hơn 100 bài viết cẩm nang từ chuyên gia thú y đầu ngành','Đọc ngay','https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=1000','#0284C7',30,'active','2026-10-11 16:54:35');
