INSERT INTO `blogs` VALUES (1,'10 Dấu hiệu nhận biết thú cưng thiếu hụt dinh dưỡng và cách bổ sung kịp thời','Dinh dưỡng','Bộ lông xơ xác, sút cân hoặc lười vận động là những tín hiệu báo động cần được bổ sung vi chất và dinh dưỡng chất lượng cao.','Dinh dưỡng đóng vai trò cốt lõi trong sức khỏe của thú cưng. Khi cơ thể thiếu hụt vi khoáng, các dấu hiệu sẽ nhanh chóng biểu hiện qua da lông và hành vi thường ngày.\n\n1. Lông rụng nhiều, mất độ bóng mượt tự nhiên: Đây là dấu hiệu của việc thiếu hụt Omega 3, Omega 6 và Kẽm. Bạn nên bổ sung dầu cá hồi hoặc thức ăn hạt chuyên dụng.\n\n2. Sụt cân hoặc giảm cơ: Lượng protein trong khẩu phần ăn không đủ để đáp ứng nhu cầu phát triển thể trạng.\n\n3. Răng ố vàng, hôi miệng: Thú cưng cần được ăn hạt khô kích thước phù hợp để hỗ trợ cọ sát làm sạch mảng bám răng.\n\nLời khuyên từ chuyên gia: Hãy lựa chọn các dòng thức ăn có nguồn gốc rõ ràng, giàu đạm động vật và không chứa chất bảo quản nhân tạo.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng & Nội khoa PetCare','4 phút đọc',1840,184,'https://images.unsplash.com/photo-1548767797-d8c844163c4c?auto=format&fit=crop&w=800','published','2026-10-11 15:48:23'),(2,'Lịch tiêm phòng và tẩy giun định kỳ chuẩn thú y cho chó mèo 2026','Sức khỏe','Bảo vệ thú cưng khỏi các bệnh truyền nhiễm nguy hiểm như Care, Parvo, Dại và Giảm bạch cầu bằng phác đồ tiêm chủng khoa học.','Tiêm chủng là biện pháp phòng bệnh chủ động và kinh tế nhất để bảo vệ mạng sống cho thú cưng ngay từ những tháng đầu đời.\n\n• Đối với chó: Mũi 1 lúc 6-8 tuần tuổi (5 bệnh), Mũi 2 sau 3-4 tuần (7 bệnh), Mũi 3 nhắc lại và Tiêm dại từ 3 tháng tuổi.\n\n• Đối với mèo: Mũi 1 lúc 8 tuần tuổi (4 bệnh gồm Giảm bạch cầu, Viêm mũi, Calicivirus), Mũi 2 sau 4 tuần, sau đó tiêm dại.\n\n• Lịch tẩy giun: Mỗi tháng 1 lần cho đến 6 tháng tuổi, sau đó duy trì định kỳ 3 tháng/lần suốt đời.','ThS. BS Trần Thu Hà','Viện Nghiên cứu Chăn nuôi Thú y','5 phút đọc',2450,246,'https://images.unsplash.com/photo-1589924691995-400dc9ecc119?auto=format&fit=crop&w=800','published','2026-10-11 15:48:23'),(3,'Bí quyết giúp cún mèo có bộ lông bóng mượt, giảm rụng lông tới 80%','Mẹo chăm sóc','Chải lông đúng cách mỗi ngày, tắm đúng tần suất và chọn đúng sữa tắm dưỡng ẩm là chìa khóa sở hữu bộ lông bồng bềnh.','Hiện tượng rụng lông ở chó mèo là hoàn toàn tự nhiên khi thay lông mùa, nhưng nếu rụng quá mức tạo thành từng mảng thì sen cần chú ý.\n\n1. Chọn đúng sữa tắm chuyên dụng: Tuyệt đối không dùng sữa tắm của người vì độ pH của da chó mèo khác biệt hoàn toàn (pH ~ 7.0 so với người ~ 5.5).\n\n2. Chải lông hàng ngày: Sử dụng lược chải gỡ rối hoặc lược lấy lông chết 5-10 phút mỗi ngày giúp kích thích lưu thông máu.\n\n3. Bổ sung dầu cá hồi và Pate chất lượng cao: Cung cấp EPA và DHA giúp nang lông chắc khỏe từ sâu bên trong.','Groomer Lê Hoàng','Chuyên gia Chăm sóc Thú cưng PetCare','3 phút đọc',1290,312,'https://images.unsplash.com/photo-1543466835-00a7907e9de1?auto=format&fit=crop&w=800','published','2026-10-11 15:48:23'),(4,'Phương pháp huấn luyện đi vệ sinh đúng chỗ chỉ sau 7 ngày kiên trì','Huấn luyện','Phương pháp huấn luyện bằng khen thưởng tích cực (Positive Reinforcement) giúp thú cưng hiểu lệnh nhanh chóng mà không gây sợ hãi.','Dạy thú cưng đi vệ sinh đúng chỗ là thử thách đầu tiên nhưng quan trọng nhất của mọi người nuôi.\n\nBước 1: Cố định vị trí khay cát hoặc tấm lót vệ sinh. Đặt ở nơi yên tĩnh, dễ tiếp cận nhưng cách xa bát ăn và nước uống.\n\nBước 2: Bắt đúng thời điểm vàng. Thông thường chó mèo sẽ muốn đi vệ sinh sau khi ngủ dậy, sau khi ăn khoảng 15-20 phút, hoặc sau khi chạy nhảy.\n\nBước 3: Khen thưởng ngay lập tức. Khi thú cưng đi đúng chỗ, hãy khen ngợi bằng giọng vui vẻ và thưởng ngay một mẩu bánh thưởng snack.','HLV. Đỗ Quốc Bảo','Huấn luyện viên Chó Chuyên nghiệp','4 phút đọc',980,198,'https://images.unsplash.com/photo-1535294435445-d7249524ef2e?auto=format&fit=crop&w=800','published','2026-10-11 15:48:23'),(5,'Cách chuyển đổi thức ăn mới cho chó mèo theo quy tắc 7 ngày vàng','Dinh dưỡng','Quy tắc 7 ngày giúp hệ tiêu hóa của thú cưng thích nghi dần, tránh tiêu chảy hoặc bỏ ăn khi đổi hạt.','Nội dung chi tiết về cách chia tỉ lệ 25% - 50% - 75% - 100% trong 7 ngày chuyển đổi thức ăn.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','3 phút đọc',1450,190,'https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=800','published','2026-10-11 16:48:03'),(6,'Dấu hiệu nhận biết mèo bị sỏi thận và giải pháp phòng ngừa từ khẩu phần','Sức khỏe','Mèo lười uống nước rất dễ bị sỏi bàng quang và thận. Hãy học cách nhận biết sớm qua thói quen đi vệ sinh.','Phân tích sỏi Struvite, Oxalate và cách tăng lượng ẩm tự nhiên bằng súp thưởng, pate và máy lọc nước.','ThS. BS Trần Thu Hà','Bác sĩ Thú y','5 phút đọc',2100,320,'https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=800','published','2026-10-11 16:48:03'),(7,'Có nên triệt sản cho thú cưng? Lợi ích sức khỏe và lưu ý sau phẫu thuật','Sức khỏe','Triệt sản giúp phòng tránh ung thư buồng trứng, tuyến tiền liệt và giảm hành vi đi lang thang, đánh dấu lãnh thổ.','Quy trình chuẩn bị trước mổ và cách chăm sóc dinh dưỡng đặc thù cho thú cưng đã triệt sản.','BS. Lê Hải Yến','Chuyên gia Ngoại khoa','4 phút đọc',1890,240,'https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=800','published','2026-10-11 16:48:03'),(8,'Bí quyết chọn cát vệ sinh khử mùi tốt và an toàn cho mèo con','Mẹo chăm sóc','So sánh ưu nhược điểm giữa cát đất sét Bentonite, cát đậu nành Tofu và cát gỗ hữu cơ.','Cách lựa chọn kích thước hạt cát và cách khử khuẩn khay cát đúng chuẩn y tế gia đình.','Groomer Lê Hoàng','Chuyên gia Chăm sóc','3 phút đọc',1120,145,'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=800','published','2026-10-11 16:48:03'),(9,'Tại sao chó mèo không nên ăn thức ăn thừa nhiều gia vị của người?','Dinh dưỡng','Gia vị muối mắm, hành tỏi và đường ngọt là những tác nhân gây suy thận, viêm tụy cấp nguy hiểm ở thú cưng.','Giải thích cơ chế chuyển hóa natri và các thực phẩm cấm kỵ như socola, nho khô, hành tây.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','4 phút đọc',2780,410,'https://images.unsplash.com/photo-1535294435445-d7249524ef2e?w=800','published','2026-10-11 16:48:03'),(10,'Hướng dẫn tắm cho mèo tại nhà không bị cào xước và không sợ nước','Mẹo chăm sóc','Các bước làm quen với nước, chọn nhiệt độ nước ấm 38 độ C và kỹ thuật giữ mèo nhẹ nhàng nhưng chắc chắn.','Kinh nghiệm sấy lông bằng máy sấy chuyên dụng chống sốc nhiệt.','Groomer Lê Hoàng','Chuyên gia Chăm sóc','5 phút đọc',1650,230,'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800','published','2026-10-11 16:48:03'),(11,'Chăm sóc răng miệng cho cún cưng: Phòng ngừa cao răng và viêm nướu','Sức khỏe','80% chó trên 3 tuổi mắc bệnh nha chu. Sử dụng que gặm DentaStix và xịt thơm miệng mỗi ngày là chìa khóa.','Hướng dẫn cách chải răng bằng bàn chải silicon và kem đánh răng vị thịt.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','3 phút đọc',980,115,'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800','published','2026-10-11 16:48:03'),(12,'Làm thế nào để trị dứt điểm ve rận và bọ chét cho chó mèo?','Sức khỏe','Vòng đời của bọ chét và cách kết hợp nhỏ gáy Frontline/NexGard với xịt diệt ấu trùng trong môi trường sống.','Phác đồ kiểm soát bọ chét toàn diện cho gia đình nuôi nhiều thú cưng.','ThS. BS Trần Thu Hà','Bác sĩ Thú y','4 phút đọc',3120,480,'https://images.unsplash.com/photo-1537151625747-768eb6cf92b2?w=800','published','2026-10-11 16:48:03'),(13,'Nhận biết hội chứng lo âu xa cách (Separation Anxiety) ở chó khi chủ vắng nhà','Huấn luyện','Cắn phá đồ đạc, sủa inh ỏi hoặc đi vệ sinh mất kiểm soát khi ở một mình là dấu hiệu của sự hoảng loạn tâm lý.','Các bài tập rời nhà ngắn hạn và đồ chơi phân tán tâm lý giúp cún cưng bình tĩnh.','HLV. Đỗ Quốc Bảo','Huấn luyện viên Chó','5 phút đọc',1420,210,'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800','published','2026-10-11 16:48:03'),(14,'Dinh dưỡng cho mèo mẹ mang thai và giai đoạn nuôi con bú','Dinh dưỡng','Nhu cầu năng lượng tăng gấp 2 - 3 lần. Cần chuyển đổi sang thức ăn hạt Kitten giàu đạm và canxi từ tuần thứ 4 thai kỳ.','Thực đơn chi tiết giúp sữa mẹ dồi dào và đàn con phát triển xương khung tối đa.','BS. Lê Hải Yến','Chuyên gia Sản nhi','4 phút đọc',1230,160,'https://images.unsplash.com/photo-1533738363-b7f9aef128ce?w=800','published','2026-10-11 16:48:03'),(15,'Cách bấm móng chân cho chó mèo an toàn không phạm vào tủy máu','Mẹo chăm sóc','Cấu tạo móng vuốt và cách nhận biết đường viền tủy hồng để cắt dứt khoát góc 45 độ.','Chuẩn bị bột cầm máu chuyên dụng đề phòng trường hợp cắt lẹm.','Groomer Lê Hoàng','Chuyên gia Chăm sóc','3 phút đọc',1780,250,'https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=800','published','2026-10-11 16:48:03'),(16,'Tìm hiểu tiêu chuẩn AAFCO trong thức ăn thú cưng: Người tiêu dùng cần biết gì?','Dinh dưỡng','AAFCO là hiệp hội kiểm soát thức ăn chăn nuôi Hoa Kỳ, đặt ra ngưỡng dinh dưỡng tối thiểu cho từng lứa tuổi.','Cách đọc bảng phân tích dinh dưỡng (Guaranteed Analysis) trên bao bì sản phẩm.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','5 phút đọc',1940,290,'https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=800','published','2026-10-11 16:48:03'),(17,'Giải pháp cải thiện tình trạng biếng ăn ở chó cưng chỉ sau 3 ngày','Mẹo chăm sóc','Nguyên nhân tâm lý hay thực thể? Áp dụng nguyên tắc không để thức ăn quá 20 phút và bổ sung súp ấm kích thích khứu giác.','Thực đơn luân phiên đổi vị tránh cảm giác ngấy hạt.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','3 phút đọc',1560,180,'https://images.unsplash.com/photo-1568640347023-a616a30bc3bd?w=800','published','2026-10-11 16:48:03'),(18,'Cảnh báo ngộ độc cây cảnh ở mèo: Các loại hoa tuyệt đối không cắm trong nhà','Sức khỏe','Hoa ly (Lily), trầu bà, kim tiền chứa độc tố gây suy thận cấp chỉ với một lượng phấn hoa dính vào lông.','Danh sách các loại cây xanh thân thiện và an toàn cho mèo nuôi trong nhà.','ThS. BS Trần Thu Hà','Bác sĩ Thú y','4 phút đọc',2890,450,'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800','published','2026-10-11 16:48:03'),(19,'Phương pháp phòng ngừa cảm lạnh và viêm phổi cho cún mùa mưa bão','Sức khỏe','Độ ẩm cao là môi trường thuận lợi cho vi khuẩn đường hô hấp phát triển. Cần sấy khô lông ngay sau khi dạo mưa.','Cách giữ ấm lồng nệm và bổ sung men vi sinh tăng cường đề kháng.','BS. Lê Hải Yến','Bác sĩ Thú y','3 phút đọc',890,110,'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800','published','2026-10-11 16:48:03'),(20,'Tầm quan trọng của Taurine đối với thị lực và tim mạch của mèo','Dinh dưỡng','Mèo không thể tự tổng hợp Taurine trong cơ thể. Thiếu hụt vi chất này dẫn đến mù lòa và giãn cơ tim vĩnh viễn.','Nguồn cung cấp Taurine dồi dào từ tim bò, cá ngừ và thức ăn công thức chuẩn.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','4 phút đọc',1670,240,'https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=800','published','2026-10-11 16:48:03'),(21,'Làm thế nào để hòa nhập một bé mèo mới vào gia đình đã có thú cưng?','Huấn luyện','Kỹ thuật cách ly phòng riêng, hoán đổi mùi hương qua khăn lau và cho ăn qua khe cửa trước khi gặp mặt trực tiếp.','Giải quyết xung đột tranh giành lãnh thổ giữa các bé.','HLV. Đỗ Quốc Bảo','Huấn luyện viên','5 phút đọc',2150,310,'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=800','published','2026-10-11 16:48:03'),(22,'Bệnh ghẻ Demodex ở chó: Nguyên nhân, triệu chứng và phác đồ điều trị dứt điểm','Sức khỏe','Ghẻ bao lông bùng phát khi hệ miễn dịch cún suy giảm. Rụng lông quanh mắt tạo hình kính râm đặc trưng.','Cách dùng thuốc trị ký sinh trùng thế hệ mới kết hợp dưỡng da phục hồi lông.','ThS. BS Trần Thu Hà','Chuyên khoa Da liễu','4 phút đọc',1840,220,'https://images.unsplash.com/photo-1535294435445-d7249524ef2e?w=800','published','2026-10-11 16:48:03'),(23,'Cách đọc hiểu ngôn ngữ cơ thể của mèo qua đuôi và ánh mắt','Mẹo chăm sóc','Đuôi dựng thẳng rung nhẹ là vui mừng, đuôi quật mạnh sang hai bên là bực bội cảnh báo sắp cào cắn.','Những cử chỉ thể hiện tình cảm tin tưởng tuyệt đối của bé mèo với chủ.','HLV. Đỗ Quốc Bảo','Huấn luyện viên','3 phút đọc',2410,380,'https://images.unsplash.com/photo-1574158622682-e40e69881006?w=800','published','2026-10-11 16:48:03'),(24,'Chế độ ăn giảm cân khoa học cho thú cưng bị béo phì','Dinh dưỡng','Béo phì rút ngắn 2 năm tuổi thọ và gây thoái hóa xương khớp sớm. Cắt giảm 15% calo và tăng cường vận động.','Sử dụng thức ăn hạt giàu chất xơ giúp thú cưng no lâu mà không nạp quá nhiều chất béo.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','4 phút đọc',1320,175,'https://images.unsplash.com/photo-1552053831-71594a27632d?w=400','published','2026-10-11 16:48:03'),(25,'Khử mùi hôi phân và nước tiểu thú cưng trong căn hộ chung cư kín khí','Mẹo chăm sóc','Sử dụng cát khử mùi hoạt tính than hoạt tính kết hợp máy lọc không khí và xịt enzym phân hủy sinh học.','Vệ sinh khay cát đúng cách định kỳ mỗi tuần.','Groomer Lê Hoàng','Chuyên gia Chăm sóc','3 phút đọc',1980,290,'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=800','published','2026-10-11 16:48:03'),(26,'Tập lệnh ngồi, nằm, bắt tay cơ bản cho cún con trong 10 phút mỗi ngày','Huấn luyện','Nguyên tắc khen thưởng tích cực bằng mẩu bánh thưởng thơm ngon ngay khi cún thực hiện đúng động tác.','Không quát mắng hoặc đánh phạt làm cún sợ hãi phản tác dụng.','HLV. Đỗ Quốc Bảo','Huấn luyện viên','4 phút đọc',2340,340,'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=400','published','2026-10-11 16:48:03'),(27,'Nhận biết sớm bệnh Parvo và Care ở chó: Giờ vàng cứu sống thú cưng','Sức khỏe','Nôn mửa ra bọt vàng, đi ngoài ra máu tanh nồng và sốt cao là dấu hiệu khẩn cấp cần đưa đến bệnh viện thú y.','Tầm quan trọng của việc truyền dịch cân bằng điện giải kịp thời.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Cấp cứu','5 phút đọc',3450,560,'https://images.unsplash.com/photo-1537151625747-768eb6cf92b2?w=800','published','2026-10-11 16:48:03'),(28,'Bảo quản thức ăn khô và thức ăn ướt đúng cách sau khi mở bao bì','Mẹo chăm sóc','Túi hạt cần được kẹp kín túi zip hoặc đổ vào thùng chân không chống ẩm mốc và kiến bọ xâm nhập.','Pate lon sau khi mở nắp phải đậy nắp silicon bảo quản tủ lạnh không quá 72 giờ.','BS. CKI Nguyễn Minh Tuấn','Trưởng khoa Dinh dưỡng','3 phút đọc',1420,195,'https://images.unsplash.com/photo-1589924691995-400dc9ecc119?w=800','published','2026-10-11 16:48:03'),(29,'Chăm sóc thú cưng già yếu (trên 7 tuổi): Những thay đổi sen cần lưu tâm','Sức khỏe','Giảm chức năng thận, đục thủy tinh thể và thoái hóa khớp là quy luật lão hóa tự nhiên của chó mèo.','Chuyển sang thức ăn công thức Senior mềm dễ nhai và bổ sung chất chống oxy hóa.','BS. Lê Hải Yến','Bác sĩ Thú y','4 phút đọc',1670,210,'https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=800','published','2026-10-11 16:48:03'),(30,'Tổng hợp lịch tiêm chủng trọn đời cho thú cưng năm 2026','Sức khỏe','Cẩm nang tra cứu nhanh các mốc tiêm phòng nhắc lại hàng năm và sổ theo dõi sức khỏe điện tử.','Bảo vệ thú cưng trọn vẹn từ lúc lọt lòng đến tuổi trưởng thành.','ThS. BS Trần Thu Hà','Bác sĩ Thú y','5 phút đọc',4200,680,'https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=800','published','2026-10-11 16:48:03');
/*!40000 ALTER TABLE `blogs` ENABLE KEYS */;
