LOCK TABLES `feedbacks` WRITE;
/*!40000 ALTER TABLE `feedbacks` DISABLE KEYS */;
INSERT INTO `feedbacks` VALUES (1,'Đỗ Thùy Linh','0912.445.566','Bé Bông','Yêu cầu tư vấn ăn uống','Mèo nhà em bị tiêu chảy sau khi đổi hạt, nhờ bác sĩ tư vấn men tiêu hóa gấp.','new','2026-10-11 22:48:23'),(2,'Vũ Tuấn Kiệt','0988.123.456','Kiki','Góp ý dịch vụ','Giao hàng hỏa tốc rất nhanh, shipper thân thiện và đóng gói chống sốc tốt.','resolved','2026-10-11 22:48:23'),(3,'Nguyễn Đức Thắng','0903.445.667','Lucky (Husky)','Yêu cầu tư vấn ăn uống','Cún nhà mình bị dị ứng ngứa da khi ăn hạt bắp, nhờ bác sĩ tư vấn hạt bò rừng.','contacting','2026-10-11 23:54:35'),(4,'Vũ Hải Đăng','0989.223.114','Milo (Phốc Sóc)','Yêu cầu tư vấn ăn uống','Cún răng yếu không nhai được hạt cứng, shop có mẫu hạt mềm ăn thử không?','resolved','2026-10-11 23:54:35'),(5,'Bùi Bích Phương','0934.778.899','Bé Mây (Ba Tư)','Yêu cầu tư vấn ăn uống','Mèo nôn búi lông nhiều, dùng gel GimCat liều lượng thế nào mỗi tuần?','resolved','2026-10-11 23:54:35'),(6,'Trần Đình Trọng','0918.441.223','Xúc Xích (Lạp Xưởng)','Yêu cầu tư vấn ăn uống','Chó bị béo phì 6.2kg cần giảm cân, xin thực đơn chi tiết từ bác sĩ.','contacting','2026-10-11 23:54:35'),(7,'Phạm Quỳnh Anh','0981.667.554','Sushi (Tai Cụp)','Yêu cầu tư vấn ăn uống','Mèo tai cụp có cần bổ sung canxi không hay chỉ cần ăn hạt Orijen?','resolved','2026-10-11 23:54:35'),(8,'Lê Tuấn Hưng','0972.889.001','Rocky (Pitbull)','Góp ý dịch vụ','Giao hỏa tốc 2h rất chuẩn giờ, shipper nhiệt tình khuân đồ lên tận phòng.','resolved','2026-10-11 23:54:35'),(9,'Ngô Kiến Huy','0908.112.334','Miu Miu (Mèo Nga)','Hỗ trợ đổi trả','Em đặt nhầm vị pate gà sang vị cá, shop hỗ trợ đổi giúp em nhé.','resolved','2026-10-11 23:54:35'),(10,'Đặng Thu Thảo','0938.556.778','Chóe (Shiba)','Yêu cầu tư vấn ăn uống','Cún thay lông rụng từng mảng, dùng dầu cá hồi bao lâu thì đỡ?','contacting','2026-10-11 23:54:35'),(11,'Dương Triệu Vũ','0919.223.889','Bông Gòn (Ragdoll)','Yêu cầu tư vấn ăn uống','Mèo kén ăn chỉ thích súp thưởng, làm sao để bé chịu ăn hạt lại?','resolved','2026-10-11 23:54:35'),(12,'Hà Anh Tuấn','0987.332.112','Bé Nâu','Yêu cầu tư vấn ăn uống','Chó ta nuôi ở vườn hay bị ve rận, dùng Frontline hay NexGard hiệu quả hơn?','resolved','2026-10-11 23:54:35'),(13,'Mai Phương Thúy','0976.445.990','Simba (Bengal)','Yêu cầu tư vấn ăn uống','Mèo vận động nhiều cần tăng cân săn chắc, xin phác đồ ăn hạt Acana.','resolved','2026-10-11 23:54:35'),(14,'Phan Mạnh Quỳnh','0902.778.112','Gấu (Samoyed)','Góp ý dịch vụ','Đóng gói túi hút chân không hạt rất kín, yên tâm không sợ mốc.','resolved','2026-10-11 23:54:35'),(15,'Nguyễn Thúc Thùy Tiên','0936.889.334','TiTi (Sphynx)','Yêu cầu tư vấn ăn uống','Mèo không lông da nhờn nhiều mụn cằm, đổi sang bát inox đỡ không ạ?','resolved','2026-10-11 23:54:35'),(16,'Trịnh Thăng Bình','0917.556.223','Mập (Pug)','Yêu cầu tư vấn ăn uống','Cún Pug ngủ ngáy to và thở khò khè, có phải do béo phì không bác sĩ?','contacting','2026-10-11 23:54:35'),(17,'Khổng Tú Quỳnh','0983.441.889','Bé Sữa (Anh Lông Dài)','Yêu cầu tư vấn ăn uống','Pate Me-O cá hồi trộn hạt có sợ bị sỏi thận không shop?','resolved','2026-10-11 23:54:35'),(18,'Bùi Anh Tuấn','0971.223.778','Cacao (Becgie)','Yêu cầu tư vấn ăn uống','Chó 4 tháng tuổi chân sau yếu, nên bổ sung Canxi Nano loại nào?','resolved','2026-10-11 23:54:35'),(19,'Hương Tràm','0907.889.445','Lulu (Xiêm)','Hỗ trợ đổi trả','Bao hạt bị rách nhẹ mép khi vận chuyển, shop đã đổi bao mới rất nhanh.','resolved','2026-10-11 23:54:35'),(20,'Soobin Hoàng Sơn','0935.112.667','Pocker (Collie)','Yêu cầu tư vấn ăn uống','Thịt sấy thăng hoa Freeze-Dried ngâm nước ấm cho ăn hay ăn khô tốt hơn?','resolved','2026-10-11 23:54:35'),(21,'Tóc Tiên','0916.445.889','Meo Meo (Mèo Mướp)','Góp ý dịch vụ','Cát đậu nành Tofu xả bồn cầu tiện lợi vô cùng, không còn mùi hôi phòng.','resolved','2026-10-11 23:54:35'),(22,'Rhymastic','0985.778.223','Bé Mực (Phú Quốc)','Yêu cầu tư vấn ăn uống','Chó hay ăn cỏ ngoài vườn có phải bị thiếu vi khoáng chất không?','contacting','2026-10-11 23:54:35'),(23,'Binz Đan Lê','0979.112.445','Oliver (Maine Coon)','Yêu cầu tư vấn ăn uống','Mèo Maine Coon cỡ to cần ăn hạt kích thước lớn loại nào phù hợp?','resolved','2026-10-11 23:54:35'),(24,'JustaTee','0901.334.889','Cookie (Bichon)','Yêu cầu tư vấn ăn uống','Cún bị vệt ố đỏ khóe mắt, ăn hạt Zenith có cải thiện được không?','resolved','2026-10-11 23:54:35'),(25,'Đen Vâu','0931.556.112','Hổ Con (Munchkin)','Yêu cầu tư vấn ăn uống','Mèo chân ngắn leo trèo nhảy cao có sợ gãy xương thoái hóa khớp không?','resolved','2026-10-11 23:54:35'),(26,'Nguyễn Văn Minh','0982.112.233','Bé Lu (Corgi)','Yêu cầu tư vấn ăn uống','Corgi ăn nhiều nhanh béo, nhờ bác sĩ tư vấn lượng gram chuẩn mỗi ngày.','resolved','2026-10-11 23:54:35'),(27,'Lê Hoàng Yến','0977.221.144','Miu Miu','Góp ý dịch vụ','Bác sĩ Tuấn tư vấn dinh dưỡng rất kỹ và có tâm, cảm ơn PetCare nhiều.','resolved','2026-10-11 23:54:35'),(28,'Trần Thu Trang','0912.889.900','Bánh Bao (Ba Tư)','Yêu cầu tư vấn ăn uống','Mèo lông dày bị xơ rối, bổ sung dầu cá hồi kết hợp chải lông hàng ngày.','resolved','2026-10-11 23:54:35'),(29,'Phạm Quốc Bảo','0933.112.233','Bé Vàng','Hỗ trợ đổi trả','Muốn đổi size balo phi hành gia từ size nhỏ lên size lớn cho cún 6kg.','resolved','2026-10-11 23:54:35'),(30,'Vũ Ngọc Mai','0909.887.766','Bơ (Poodle)','Yêu cầu tư vấn ăn uống','Poodle lông bạc màu rụng nhiều, xin phác đồ men vi sinh và vitamin.','contacting','2026-10-11 23:54:35');
/*!40000 ALTER TABLE `feedbacks` ENABLE KEYS */;
