INSERT INTO `reviews` VALUES (1,1,'Hạt Royal Canin Fit 32 Cho Mèo Trưởng Thành (Bao 2kg)',2,'Lê Hoàng Yến','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Mèo nhà mình ăn Fit 32 từ bé, trộm vía lông mượt như nhung, không hề bị rụng lông hay sỏi thận. Đóng gói rất kỹ càng!','Bao 2.0 kg',1,14,'approved','2026-10-02 09:15:00'),(2,6,'Bánh Thưởng Cho Mèo Ciao Churu Vị Gà & Sò Điệp',1,'Nguyễn Văn Minh','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Bé Miu nhà mình nghiện Churu này lắm, chỉ cần nghe tiếng xé gói là chạy bổ lại ngay. Rất thơm và sạch miệng!','Gói 4 thanh (56g)',1,28,'approved','2026-10-03 14:30:00'),(3,8,'(1 tải 6 bao) Cát Nhật đen MoonCat 9L chính hãng Khử Mùi Vón Cục',3,'Trần Thu Trang','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Cát hút mùi cực tốt, vón cục cứng ngắc không bị vỡ vụn khi xúc, ít bụi hơn hẳn các loại trước đây mình dùng.','1 Tải 6 bao',1,9,'approved','2026-10-05 16:45:00'),(4,10,'Pate Cho Chó Pedigree Lon Vị Thịt Bò & Rau Củ (Lon 400g)',1,'Nguyễn Văn Minh','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Pate thơm nức mũi, trộn cùng hạt cún ăn sạch sành sanh không chừa một hạt nào.','Lon 400g',1,12,'approved','2026-10-08 11:20:00'),(5,11,'Hạt Cho Chó Ganador Vị Cừu & Gạo',6,'Đỗ Minh Trí','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Hạt cừu rất thơm, cún nhà mình ăn không bị dị ứng hay ngứa da như mấy loại gà trước đây.','Túi 1.5kg',1,15,'approved','2026-10-01 10:00:00'),(6,12,'Hạt Cho Mèo Catsrang Nhập Khẩu Hàn Quốc',7,'Hoàng Thu Ngân','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Mèo ăn tiêu hóa tốt, ít mùi hôi phân hẳn. Giá lại quá hợp lý cho học sinh sinh viên.','Túi 2kg',1,32,'approved','2026-10-02 12:30:00'),(7,20,'Hạt Không Ngũ Cốc Taste of the Wild Bison',8,'Nguyễn Đức Thắng','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',5,'Đúng chuẩn hạt cao cấp, cún Husky ăn